import { createRoot } from 'react-dom/client';
import './index.css';
// Import React and necessary components from React Diagram library for building the diagram.
import * as React from "react";
import { HierarchicalTree, DataBinding, DiagramComponent, Inject, DiagramTools } from "@syncfusion/ej2-react-diagrams";

import { DataManager } from "@syncfusion/ej2-data";
function RemoteData() {
    // 1) Memoize DataManager so it is not recreated on re-renders
    const dataManager = React.useMemo(() => {
        return new DataManager({
            url: "https://services.syncfusion.com/react/production/api/RemoteData",
            crossDomain: true
        });
    }, []);
    // 2) Memoize layout object to keep stable identity
    const layout = React.useMemo(() => ({
        type: "HierarchicalTree",
        margin: { left: 0, right: 0, top: 100, bottom: 0 },
        verticalSpacing: 40
    }), []);
    // 3) Stable callbacks for defaults/binding
    const getNodeDefaults = React.useCallback((node) => {
        node.width = 80;
        node.height = 40;
        node.shape = { type: "Basic", shape: "Rectangle" };
        node.style = { fill: "#048785", strokeColor: "Transparent" };
    }, []);
    const getConnectorDefaults = React.useCallback((connector) => {
        connector.type = "Orthogonal";
        connector.style.strokeColor = "#048785";
        connector.targetDecorator.shape = "None";
    }, []);
    const doBinding = React.useCallback((nodeModel, data) => {
        nodeModel.annotations = [
            {
                content: data["Label"],
                style: { color: "white" }
            }
        ];
    }, []);
    // 4) Memoize dataSourceSettings so its identity is stable
    const dataSourceSettings = React.useMemo(() => ({
        id: "Id",
        parentId: "ParentId",
        dataSource: dataManager,
        doBinding
    }), [dataManager, doBinding]);
    return (<div className="control-pane">
            <div className="control-section">
                <DiagramComponent id="diagram" width={"100%"} height={"490"} layout={layout} getNodeDefaults={getNodeDefaults} getConnectorDefaults={getConnectorDefaults} dataSourceSettings={dataSourceSettings} tool={DiagramTools.ZoomPan} snapSettings={{ constraints: 0 }}>
                    <Inject services={[DataBinding, HierarchicalTree]}/>
                </DiagramComponent>
            </div>
        </div>);
}
export default RemoteData;

const root = createRoot(document.getElementById('sample'));
root.render(<RemoteData />);
